import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class SecureFileAccess {
    public void readLogFile(String fileName) {
        // Base directory for safe file operations
        String baseDir = "/var/logs/";

        // Construct the path using Path API to ensure it remains within the intended directory
        Path basePath = Paths.get(baseDir);
        Path requestedPath = basePath.resolve(fileName).normalize();

        // Ensure the resolved path does not escape the base directory (e.g., via ../ sequences)
        if (!requestedPath.startsWith(basePath)) {
            throw new SecurityException("Attempt to access file outside of allowed directory.");
        }

        File file = requestedPath.toFile();

        if (file.exists() && file.isFile()) {
            System.out.println("Reading secure file: " + file.getAbsolutePath());
        }
    }
}
